#!/bin/bash
# Generated by dsh-super-injector dev_scaffold_plugin; patched with fallback mode.
# 优先用 DSH checkout 源码树（vendor/packages 布局）；
# 找不到 checkout 时回退：junction 链接本机现成依赖树（super-injector + npm 版 dsh），
# 用注入器自带 typescript 编译。两条路径产物一致（lib/）。
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"

INJ_NM="${INJ_NODE_MODULES:-E:/WorkSpace/Tools/dsh-super-injector/node_modules}"
NPM_DSH_NM="${NPM_DSH_NODE_MODULES:-C:/Users/Sumcam/AppData/Roaming/npm/node_modules/@deepseek-ai/dsh/node_modules}"

# DSH_CHECKOUT 探测：环境变量 → 常见路径
CHECKOUT="${DSH_CHECKOUT:-}"
if [ -z "$CHECKOUT" ]; then
  for candidate in "$HOME/dsh-harness" "$HOME/dsh" "$HOME/.dsh/dsh-harness"; do
    if [ -d "$candidate/packages" ]; then CHECKOUT="$candidate"; break; fi
  done
fi

link_pkg() {
  local link="$1" target="$2"
  if [ -e "$link" ]; then return 0; fi
  if [ ! -e "$target" ]; then echo "build: dependency target missing: $target" >&2; exit 1; fi
  node -e "
    const fs = require('fs');
    const path = require('path');
    fs.mkdirSync(path.dirname(process.argv[1]), { recursive: true });
    fs.symlinkSync(path.resolve(process.argv[2]), path.resolve(process.argv[1]), process.platform === 'win32' ? 'junction' : 'dir');
  " "$link" "$target"
}

if [ -n "$CHECKOUT" ] && [ -d "$CHECKOUT/packages" ]; then
  echo "=== Build mode: DSH checkout ($CHECKOUT) ==="
  TSC="$CHECKOUT/node_modules/.bin/tsc"
  [ -x "$TSC" ] || [ -f "$TSC.cmd" ] || { echo "build: tsc not found at $TSC" >&2; exit 1; }
  mkdir -p node_modules/@deepseek-ai
  node -e "const fs=require('fs');fs.rmSync('node_modules/@standard-schema',{recursive:true,force:true})"
  link_pkg node_modules/cordis "$CHECKOUT/vendor/cordis"
  link_pkg node_modules/cosmokit "$CHECKOUT/vendor/cosmokit"
  link_pkg node_modules/schemastery "$CHECKOUT/vendor/schemastery"
  link_pkg node_modules/@deepseek-ai/dsh-tools "$CHECKOUT/packages/core/tools"
  link_pkg node_modules/@deepseek-ai/dsh-llm "$CHECKOUT/packages/llm/llm"
  link_pkg node_modules/@types/node "$CHECKOUT/node_modules/@types/node"
  "$TSC" -p tsconfig.json
else
  echo "=== Build mode: fallback (injector + npm dsh trees) ==="
  TSC_BIN="$INJ_NM/typescript/bin/tsc"
  [ -f "$TSC_BIN" ] || { echo "build: typescript not found at $TSC_BIN" >&2; exit 1; }
  link_pkg node_modules/cordis "$INJ_NM/cordis"
  link_pkg node_modules/schemastery "$INJ_NM/schemastery"
  link_pkg node_modules/@deepseek-ai/dsh-tools "$NPM_DSH_NM/@deepseek-ai/dsh-tools"
  link_pkg node_modules/@deepseek-ai/dsh-llm "$NPM_DSH_NM/@deepseek-ai/dsh-llm"
  link_pkg node_modules/@types/node "$NPM_DSH_NM/@types/node"
  node "$TSC_BIN" -p tsconfig.json
fi

echo "=== Build complete ==="
